DECLARATIONS.update({'append_current_city_owner_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_gameplay_flow.contexts_services import SceneRefreshMemory\nfrom ..high_level_scene_flows.business_scene import _scene_render_asl_word\nframe = _city_ui_frame_fields(state, frame, 22336)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964068, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)\nframe = _movement_move(state, frame, 'target_y', 0, 16)\nwhile True:\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_x', 10, True)\n    if frame.status & 1:\n        break\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_y', 1)\nframe = _city_ui_arithmetic_fields(state, frame, 'target_x', 10)\nframe = _movement_test(state, frame, low16(frame.target_y), 16)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'target_y', 49153, 16)\nelse:\n    frame = _city_ui_shift_fields(state, frame, 'target_y', 2)\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_y', 49368)\nframe = _city_ui_child_fields(state, frame, 22396, 22380)\nframe = _scene_render_asl_word(SceneRefreshMemory(state), frame, 'target_x', low16(frame.target_x), 2)\nframe = _movement_arithmetic_long(state, frame, 'target_x', 49368)\nframe = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)\nreturn _city_ui_child_fields(state, frame, 22396, 22394)"}})

