DECLARATIONS.update({'update_selected_force_prompt_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 42288)\nframe = _city_ui_memory_arithmetic_fields(state, frame, 4294964744, 1, True)\nif not frame.status & 4:\n    return frame\nframe = _city_ui_store_fields(state, frame, 4294964744, 8)\nframe = _movement_move(state, frame, 'target_x', state.read(4294964738, 1), 8)\nframe = _movement_move(state, frame, 'target_y', state.read(4294964060, 2), 16)\ndirection = None\nfor bit in (0, 1, 3, 2):\n    frame = _city_ui_bit_fields(state, frame, frame.target_x, bit)\n    if not frame.status & 4:\n        direction = bit\n        break\nif direction is None:\n    return _city_ui_store_fields(state, frame, 4294964744, 1)\nif direction == 0:\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 7, 16)\n    if not frame.status & 4:\n        return _city_ui_memory_arithmetic_fields(state, frame, 4294964060, 1, True)\n    frame = _movement_move(state, frame, 'target_y', 7, 16)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964056, 14, True)\n    if frame.status & 1:\n        frame = _city_ui_store_fields(state, frame, 4294964056, 29)\n        frame = _movement_move(state, frame, 'target_y', 6, 16)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964060, low16(frame.target_y))\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964754, 1)\n    return _city_ui_store_fields(state, frame, 4294964058, 0, 2, True)\nif direction == 1:\n    frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) & 7, 16)\n    frame = _movement_compare(state, frame, low16(frame.target_y), 7, 16)\n    wrap = not bool(frame.status & 1)\n    if not wrap:\n        frame = _movement_compare(state, frame, state.read(4294964056, 2), 29, 16)\n        if frame.status & 4:\n            frame = _movement_compare(state, frame, low16(frame.target_y), 6, 16)\n            wrap = not bool(frame.status & 1)\n    if not wrap:\n        return _city_ui_memory_arithmetic_fields(state, frame, 4294964060, 1)\n    frame = _movement_move(state, frame, 'target_y', 7, 16)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964056, 14)\n    frame = _movement_compare(state, frame, state.read(4294964056, 2), 40, 16)\n    if not frame.status & 1:\n        frame = _movement_move(state, frame, 'target_y', 6, 16)\n        frame = _city_ui_store_fields(state, frame, 4294964056, 1)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964060, low16(frame.target_y), True)\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964754, 1)\n    return _city_ui_store_fields(state, frame, 4294964058, 0, 2, True)\nif direction == 3:\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_y', 8)\n    frame = _movement_compare(state, frame, low16(frame.target_y), 16, 16)\n    if not frame.status & 1:\n        return frame\n    frame = _city_ui_memory_arithmetic_fields(state, frame, 4294964060, 8)\n    if not frame.status & 1:\n        return frame\nframe = _city_ui_arithmetic_fields(state, frame, 'target_y', 8, True)\nif frame.status & 8:\n    return frame\nreturn _city_ui_memory_arithmetic_fields(state, frame, 4294964060, 8, True)"}})

