DECLARATIONS.update({'_campaign_ui_change_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, bit: int, set_bit: bool', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_gameplay_flow.contexts_services import SceneRefreshMemory\nfrom ..high_level_gameplay_flow.business_services import _scene_refresh_bit_set, _scene_refresh_bit_clear\nif type(set_bit) is not bool:\n    raise ValueError('actual command bit operation required')\nif set_bit:\n    return _scene_refresh_bit_set(SceneRefreshMemory(state), frame, address, bit)\nreturn _scene_refresh_bit_clear(SceneRefreshMemory(state), frame, address, bit)"}})

DECLARATIONS.update({'compose_command_selection_prompt_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 22496)\nframe = _campaign_ui_call_fields(state, frame, 23106, 22500)\nframe = _campaign_ui_parallel_cell_fields(state, frame, 50050, (30, 60))\nframe = _movement_move(state, frame, 'choice', state.read(4294964074, 2), 16)\nframe = _city_ui_arithmetic_fields(state, frame, 'choice', state.read(4294964072, 2))\nframe = _city_ui_shift_fields(state, frame, 'choice', 2)\nframe = first_replace(frame, candidates=state.table_at(565942).cursor())\nframe = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.choice)), 16)\nframe = _campaign_ui_call_fields(state, frame, 23082, 22540)\nframe = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.choice), 2), 16)\nframe = _campaign_ui_call_fields(state, frame, 23082, 22548)\nframe = _movement_fixed_shift_word(state, frame, 'choice', 1, True)\nframe = _movement_move(state, frame, 'choice', state.table_at(22602).word(low16(frame.choice)), 16)\ntarget = u32(22628 + s16(low16(frame.choice)))\nframe = _campaign_ui_call_fields(state, frame, target, 22558)\nframe = _campaign_ui_parallel_cell_fields(state, frame, 52098, (30, 60))\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _movement_move(state, frame, 'count', 10, 16)\nwhile True:\n    frame = _city_ui_store_fields(state, frame, u32(frame.roster.base + s16(low16(frame.unit)) + 36), 49153)\n    frame = _city_ui_arithmetic_fields(state, frame, 'unit', 2)\n    frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count) - 1)))\n    if low16(frame.count) == 65535:\n        break\nframe = _city_ui_store_fields(state, frame, u32(frame.roster.base + 60), 0, 2, True)\nreturn _city_ui_memory_arithmetic_fields(state, frame, 4294964074, 1)"}})

