DECLARATIONS.update({'append_command_selection_heading_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 23106)\nframe = first_replace(frame, roster=state.table_at(u32(4294955264 + s16(state.read(4294963994, 2)))).cursor())\nframe = _campaign_ui_parallel_cell_fields(state, frame, 13, (60, 30))\nframe = _movement_move(state, frame, 'unit', state.read(4294964074, 2), 16)\nframe = _movement_move(state, frame, 'count', low16(frame.unit), 16)\nframe = _city_ui_shift_fields(state, frame, 'unit', 1)\nframe = _city_ui_arithmetic_fields(state, frame, 'unit', low16(frame.count))\nframe = _city_ui_shift_fields(state, frame, 'unit', 7)\nframe = _city_ui_arithmetic_fields(state, frame, 'unit', 49588)\nfor offset in (0, 30, 60):\n    if offset:\n        frame = _city_ui_arithmetic_fields(state, frame, 'unit', 128)\n    frame = _city_ui_store_fields(state, frame, u32(frame.roster.base + offset), low16(frame.unit))\nreturn first_replace(frame, roster=frame.roster.advance(2))"}})

DECLARATIONS.update({'append_command_confirmation_row_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 23168)\nframe = first_replace(frame, roster=state.table_at(u32(4294955264 + s16(state.read(4294963994, 2)))).cursor())\nframe = _city_ui_append_fields(state, frame, 13)\nframe = _movement_move(state, frame, 'unit', state.read(4294964074, 2), 16)\nframe = _movement_move(state, frame, 'count', low16(frame.unit), 16)\nframe = _city_ui_shift_fields(state, frame, 'unit', 1)\nframe = _city_ui_arithmetic_fields(state, frame, 'unit', low16(frame.count))\nframe = _city_ui_shift_fields(state, frame, 'unit', 7)\nframe = _city_ui_arithmetic_fields(state, frame, 'unit', 49588)\nframe = _city_ui_append_fields(state, frame, low16(frame.unit))\nframe = _city_ui_append_fields(state, frame, 54144)\nframe = _movement_move(state, frame, 'target_x', 10, 16)\nwhile True:\n    frame = _city_ui_append_fields(state, frame, 54145)\n    frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))\n    if low16(frame.target_x) == 65535:\n        break\nframe = _city_ui_append_fields(state, frame, 56192)\nframe = _city_ui_store_fields(state, frame, frame.roster.base, 0, 2, True)\nreturn _city_ui_memory_arithmetic_fields(state, frame, 4294963994, 30)"}})

DECLARATIONS.update({'present_current_command_prompt_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 23228)\nframe = _movement_compare(state, frame, state.read(4294964108, 2), 129, 16)\nif frame.status & 4:\n    return frame\nframe = _movement_move_long(state, frame, 'target_x', 3221225483)\nframe = _movement_move(state, frame, 'target_y', 4, 16)\nframe = _movement_move(state, frame, 'choice', state.read(4294964076, 2), 16)\nframe = _city_ui_shift_fields(state, frame, 'choice', 1)\nframe = _movement_move(state, frame, 'choice', state.table_at(23270).word(low16(frame.choice)), 16)\nreturn _campaign_ui_call_fields(state, frame, u32(23278 + s16(low16(frame.choice))), 23262)"}})

