DECLARATIONS.update({'append_title_option_digit_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 43518)\nframe = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)\nframe = _movement_compare(state, frame, low16(frame.target_x), 10, 16)\nif frame.status & 1:\n    frame = _movement_move(state, frame, 'unit', 552, 16)\nelse:\n    frame = _movement_move(state, frame, 'unit', 0, 16)\n    while True:\n        frame = _city_ui_arithmetic_fields(state, frame, 'distance', 10, True)\n        if frame.status & 1:\n            break\n        frame = _city_ui_arithmetic_fields(state, frame, 'unit', 1)\n    frame = _city_ui_arithmetic_fields(state, frame, 'distance', 10)\n    frame = _city_ui_shift_fields(state, frame, 'unit', 2)\n    frame = _city_ui_arithmetic_fields(state, frame, 'unit', 1034)\nframe = _campaign_ui_call_fields(state, frame, 43572, 43558)\nframe = _movement_move(state, frame, 'unit', low16(frame.distance), 16)\nframe = _city_ui_shift_fields(state, frame, 'unit', 2)\nframe = _city_ui_arithmetic_fields(state, frame, 'unit', 1034)\nreturn _campaign_ui_call_fields(state, frame, 43572, 43570)"}})

DECLARATIONS.update({'store_title_option_digit_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 43572)\nfor _column in (0, 1):\n    frame = _city_ui_store_fields(state, frame, frame.roster.base, low16(frame.unit))\n    frame = _city_ui_arithmetic_fields(state, frame, 'unit', 1)\n    frame = _city_ui_store_fields(state, frame, u32(frame.roster.base + 22), low16(frame.unit))\n    frame = first_replace(frame, roster=frame.roster.advance(2))\n    if _column == 0:\n        frame = _city_ui_arithmetic_fields(state, frame, 'unit', 1)\nreturn frame"}})

DECLARATIONS.update({'set_title_option_marker_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 43596)\nframe = _campaign_ui_parallel_cell_fields(state, frame, 1155, (22,))\nframe = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)\nframe = _city_ui_shift_fields(state, frame, 'unit', 3)\nframe = _city_ui_arithmetic_fields(state, frame, 'unit', 696)\nframe = _movement_move(state, frame, 'count', 3, 16)\nwhile True:\n    frame = _city_ui_store_fields(state, frame, frame.roster.base, low16(frame.unit))\n    frame = _city_ui_arithmetic_fields(state, frame, 'unit', 1)\n    frame = _city_ui_store_fields(state, frame, u32(frame.roster.base + 22), low16(frame.unit))\n    frame = _city_ui_arithmetic_fields(state, frame, 'unit', 1)\n    frame = first_replace(frame, roster=frame.roster.advance(2), count=replace_word(frame.count, u16(low16(frame.count) - 1)))\n    if low16(frame.count) == 65535:\n        break\nreturn frame"}})

DECLARATIONS.update({'append_title_option_decorations_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "from .business_movement_support import _movement_save_longs, _movement_restore_longs\nframe = _city_ui_frame_fields(state, frame, 43636)\nsaved = ('target_x', 'target_y', 'unit', 'count', 'distance', 'offset_x', 'offset_y', 'candidates', 'auxiliary')\nframe = _movement_save_longs(state, frame, saved)\nframe = _movement_move(state, frame, 'unit', 22, 16)\nframe = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.unit))))\nframe = _city_ui_append_fields(state, frame, 1155)\nframe = first_replace(frame, candidates=state.table_at(4294964263).cursor())\nframe = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.target_x)), 8)\nframe = _movement_compare(state, frame, low8(frame.unit), state.read(4294964087, 1), 8)\nif not frame.status & 4:\n    frame = _campaign_ui_call_fields(state, frame, 43792, 43670)\nelse:\n    frame = _movement_move(state, frame, 'unit', state.read(4294964048, 2), 16)\n    frame = _city_ui_shift_fields(state, frame, 'unit', 1)\n    frame = _movement_move(state, frame, 'unit', state.table_at(43692).word(low16(frame.unit)), 16)\n    frame = _campaign_ui_call_fields(state, frame, u32(43700 + s16(low16(frame.unit))), 43686)\nreturn _movement_restore_longs(state, frame, saved)"}})

DECLARATIONS.update({'append_title_option_decoration_value_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 43792)\nfor counter, tile in ((3, 49704), (1, 1160)):\n    frame = _movement_move(state, frame, 'unit', counter, 16)\n    while True:\n        frame = _city_ui_append_fields(state, frame, tile)\n        frame = first_replace(frame, unit=replace_word(frame.unit, u16(low16(frame.unit) - 1)))\n        if low16(frame.unit) == 65535:\n            break\nreturn frame"}})

