DECLARATIONS.update({'append_city_command_heading_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 55470)\nframe = first_replace(frame, roster=state.table_at(u32(4294955264 + s16(state.read(4294963994, 2)))).cursor())\nframe = _movement_move(state, frame, 'target_x', 50080, 16)\nframe = _movement_move(state, frame, 'target_y', 32773, 16)\nframe = _movement_move(state, frame, 'unit', 7, 16)\nwhile True:\n    frame = _city_ui_append_fields(state, frame, 6)\n    frame = _city_ui_append_fields(state, frame, low16(frame.target_x))\n    frame = _city_ui_arithmetic_fields(state, frame, 'target_x', 128)\n    frame = _movement_move(state, frame, 'count', 5, 16)\n    while True:\n        frame = _city_ui_append_fields(state, frame, low16(frame.target_y))\n        frame = _city_ui_arithmetic_fields(state, frame, 'target_y', 1)\n        frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count) - 1)))\n        if low16(frame.count) == 65535:\n            break\n    frame = first_replace(frame, unit=replace_word(frame.unit, u16(low16(frame.unit) - 1)))\n    if low16(frame.unit) == 65535:\n        break\nframe = _city_ui_store_fields(state, frame, frame.roster.base, 0, 2, True)\nframe = _city_ui_memory_arithmetic_fields(state, frame, 4294963994, 128)\nreturn _campaign_ui_change_bit_fields(state, frame, 4294964133, 2, True)"}})

DECLARATIONS.update({'append_current_command_description_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 55532)\nframe = _city_ui_bit_fields(state, frame, state.read(4294964133, 1), 2)\nif frame.status & 4:\n    return frame\nframe = _campaign_ui_call_fields(state, frame, 55852, 55544)\nframe = _campaign_ui_call_fields(state, frame, 55950, 55548)\nframe = first_replace(frame, roster=state.table_at(55672).cursor())\nframe = _movement_move(state, frame, 'target_x', 56, 16)\nframe = _movement_move(state, frame, 'target_y', 128, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _city_ui_store_fields(state, frame, 4294964746, 0, 2, True)\nframe = _city_ui_store_fields(state, frame, 4294964750, 0, 2, True)\nframe = _campaign_ui_call_fields(state, frame, 55584, 55576)\nreturn _campaign_ui_call_fields(state, frame, 44040, 55582)"}})

DECLARATIONS.update({'choose_command_description_source_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 55584)\nframe = _movement_compare(state, frame, state.read(4294964066, 2), 7, 16)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'count', state.read(4294964074, 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.count), 6, 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        return frame\n    frame = _city_ui_arithmetic_fields(state, frame, 'count', 2, True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'count', 0, 16)\n    frame = _city_ui_shift_fields(state, frame, 'count', 2)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294964066, 2), 3, 16)\n    if not frame.status & 4:\n        return frame\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), 3, 16)\n    if frame.status & 1 or frame.status & 4:\n        return frame\n    frame = _movement_move(state, frame, 'count', 10, 16)\n    frame = _city_ui_arithmetic_fields(state, frame, 'count', state.read(4294964074, 2), True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'count', 0, 16)\n    frame = _city_ui_shift_fields(state, frame, 'count', 1)\nframe = first_replace(frame, candidates=state.table_at(55834).cursor())\nframe = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.count)), 16)\nreturn first_replace(frame, roster=frame.roster.advance(s16(low16(frame.count))))"}})

DECLARATIONS.update({'append_command_description_rows_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 55852)\nframe = _movement_compare(state, frame, state.read(4294964066, 2), 3, 16)\nif frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), 7, 16)\n    if not frame.status & 1:\n        return frame\nelse:\n    frame = _movement_compare(state, frame, state.read(4294964066, 2), 7, 16)\n    if frame.status & 4:\n        frame = _movement_compare(state, frame, state.read(4294964074, 2), 4, 16)\n        if frame.status & 1 or frame.status & 4:\n            return frame\nframe = first_replace(frame, roster=state.table_at(55934).cursor())\nframe = _movement_move(state, frame, 'target_x', state.read(4294964000, 2), 16)\nframe = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 248, 16)\nif frame.status & 4:\n    frame = first_replace(frame, roster=frame.roster.advance(8))\nframe = _movement_move(state, frame, 'target_x', 80, 16)\nframe = _movement_move(state, frame, 'target_y', 136, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nreturn _campaign_ui_call_fields(state, frame, 44040, 55932)"}})

DECLARATIONS.update({'append_command_description_status_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 55950)\nframe = _movement_compare(state, frame, state.read(4294964066, 2), 3, 16)\nif frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), 5, 16)\n    if not frame.status & 1:\n        return frame\nelse:\n    frame = _movement_compare(state, frame, state.read(4294964066, 2), 7, 16)\n    if frame.status & 4:\n        frame = _movement_compare(state, frame, state.read(4294964074, 2), 5, 16)\n        if frame.status & 1 or frame.status & 4:\n            return frame\nframe = first_replace(frame, roster=state.table_at(56080).cursor())\nframe = _movement_test(state, frame, state.read(4294965112, 2), 16)\nif not frame.status & 4:\n    frame = _city_ui_bit_fields(state, frame, state.read(4294964001, 1), 3)\n    if not frame.status & 4:\n        frame = first_replace(frame, roster=frame.roster.advance(8))\nframe = _movement_move(state, frame, 'target_x', 96, 16)\nframe = _movement_move(state, frame, 'target_y', 144, 16)\nframe = _movement_move(state, frame, 'unit', 0, 16)\nframe = _campaign_ui_call_fields(state, frame, 44040, 56036)\nframe = _movement_test(state, frame, state.read(4294965112, 2), 16)\nif not frame.status & 4:\n    frame = _movement_compare(state, frame, state.read(4294965116, 2), 16442, 16)\n    if frame.status & 4:\n        frame = _city_ui_store_fields(state, frame, 4294965112, 0, 2, True)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294965116, 2), 16441, 16)\n    if frame.status & 4:\n        frame = _city_ui_store_fields(state, frame, 4294965112, 1)\nreturn frame"}})

