# C50 first fresh failures: exact reconstruction corrections; zero new credit.
DECLARATIONS.update({'_campaign_ui_change_bit_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame, address: int, bit: int, set_bit: bool', 'returns': 'FirstDeploymentFrame', 'flow': "from ..high_level_gameplay_flow.contexts_services import SceneRefreshMemory\nfrom ..high_level_gameplay_flow.business_services import _scene_refresh_bit_clear\nif type(set_bit) is not bool:\n    raise ValueError('actual command bit operation required')\nif set_bit:\n    previous = state.read(address, 1)\n    frame = _city_ui_bit_fields(state, frame, previous, bit)\n    state.write(address, 1, previous | 1 << bit)\n    return frame\nreturn _scene_refresh_bit_clear(SceneRefreshMemory(state), frame, address, bit)"}})
DECLARATIONS.update({'present_current_command_prompt_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 23228)\nframe = _movement_compare(state, frame, state.read(4294964108, 2), 129, 16)\nif frame.status & 4:\n    return frame\nframe = _movement_move_long(state, frame, 'target_x', 3221225483)\nframe = _movement_move(state, frame, 'target_y', 4, 16)\nframe = _movement_move(state, frame, 'choice', state.read(4294964076, 2), 16)\nframe = _city_ui_shift_fields(state, frame, 'choice', 1)\nframe = _movement_move(state, frame, 'choice', state.table_at(23270).word(low16(frame.choice)), 16)\nframe = _campaign_ui_call_fields(state, frame, u32(23278 + s16(low16(frame.choice))), 23262)\nreturn _campaign_ui_change_bit_fields(state, frame, 4294964132, 3, True)"}})
DECLARATIONS.update({'choose_command_description_source_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'flow': "frame = _city_ui_frame_fields(state, frame, 55584)\nframe = _movement_compare(state, frame, state.read(4294964066, 2), 7, 16)\nif frame.status & 4:\n    frame = _movement_move(state, frame, 'count', state.read(4294964074, 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.count), 6, 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        return frame\n    frame = _city_ui_arithmetic_fields(state, frame, 'count', 2, True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'count', 0, 16)\n    frame = _city_ui_shift_fields(state, frame, 'count', 2)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294964066, 2), 3, 16)\n    if not frame.status & 4:\n        return frame\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), 3, 16)\n    if frame.status & 1 or frame.status & 4:\n        return frame\n    frame = _movement_move(state, frame, 'count', 10, 16)\n    frame = _city_ui_arithmetic_fields(state, frame, 'count', state.read(4294964074, 2), True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'count', 0, 16)\n    frame = _city_ui_shift_fields(state, frame, 'count', 1)\nframe = first_replace(frame, candidates=state.table_at(55836).cursor())\nframe = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.count)), 16)\nreturn first_replace(frame, roster=frame.roster.advance(s16(low16(frame.count))))"}})

# Exact original two-role PC-relative bases: D946=DA1C, D96A=DA1A.
DECLARATIONS.update({'choose_command_description_source_frame_fields': {'signature': 'state: SceneState, frame: FirstDeploymentFrame', 'returns': 'FirstDeploymentFrame', 'rules': {}, 'flow': "frame = _city_ui_frame_fields(state, frame, 55584)\ntable_base = 55836\nframe = _movement_compare(state, frame, state.read(4294964066, 2), 7, 16)\nif frame.status & 4:\n    table_base = 55834\n    frame = _movement_move(state, frame, 'count', state.read(4294964074, 2), 16)\n    frame = _movement_compare(state, frame, low16(frame.count), 6, 16)\n    if not frame.status & 1 and (not frame.status & 4):\n        return frame\n    frame = _city_ui_arithmetic_fields(state, frame, 'count', 2, True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'count', 0, 16)\n    frame = _city_ui_shift_fields(state, frame, 'count', 2)\nelse:\n    frame = _movement_compare(state, frame, state.read(4294964066, 2), 3, 16)\n    if not frame.status & 4:\n        return frame\n    frame = _movement_compare(state, frame, state.read(4294964074, 2), 3, 16)\n    if frame.status & 1 or frame.status & 4:\n        return frame\n    frame = _movement_move(state, frame, 'count', 10, 16)\n    frame = _city_ui_arithmetic_fields(state, frame, 'count', state.read(4294964074, 2), True)\n    if frame.status & 8:\n        frame = _movement_move(state, frame, 'count', 0, 16)\n    frame = _city_ui_shift_fields(state, frame, 'count', 1)\nframe = first_replace(frame, candidates=state.table_at(table_base).cursor())\nframe = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.count)), 16)\nreturn first_replace(frame, roster=frame.roster.advance(s16(low16(frame.count))))"}})

